import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            S = next(iterator)
            K = int(next(iterator))
        except StopIteration:
            break

        n = len(S)
        stack = []
        remaining_needed = K

        for i, char in enumerate(S):
            chars_left_after_i = n - i - 1

            while stack and stack[-1] > char and (len(stack) - 1 + chars_left_after_i) >= remaining_needed:
                stack.pop()

            if len(stack) < remaining_needed:
                stack.append(char)

        results.append("".join(stack))

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
